B.aAt=new A.Z("\u0130lan Detay\u0131",null,null,null,null,null,null,null,null,null)
B.aAv=new A.Z("At sahipleri atlar\u0131n\u0131n neyle ta\u015f\u0131naca\u011f\u0131n\u0131 g\xf6rmek ister. Bir kez ekleyin, t\xfcm ilan ve tekliflerinizde g\xf6r\xfcn\xfcr.",null,B.bb,null,null,null,null,null,null,null)
B.aAw=new A.Z("At sahipleri atlar\u0131n\u0131n hangi ara\xe7la ta\u015f\u0131naca\u011f\u0131n\u0131 g\xf6rmek ister. Foto\u011fraflar\u0131n\u0131z bo\u015f ara\xe7 ilanlar\u0131n\u0131zda ve verdi\u011finiz tekliflerde otomatik g\xf6r\xfcn\xfcr; foto\u011frafl\u0131 teklifler daha \xe7ok g\xfcven verir.",null,B.ff,null,null,null,null,null,null,null)
